export const QUESTIONS = raw.trim().split('\n').filter(Boolean).map((line,index)=>{
  const [category,page,stem,correct,...rest]=line.split('|');
  const [b,c,d,explanation,sample]=rest;
  const choices=[correct,b,c,d];
  const shift=index%4;
  const options=choices.map((_,i)=>choices[(i-shift+4)%4]);
  return {id:`B${String(index+1).padStart(3,'0')}`,category,stem,options,answer:shift,explanation,page:Number(page),sample:sample?Number(sample):null,checked:CHECKED};
});
